import frappe
from frappe.model.document import Document

class PayFinalSettlement(Document):
    def before_save(self):
        # --- from script: Decompte Final Full (exec fallback) ---
        script = "if doc.employee:\n \n  date_actuelle_end = frappe.utils.getdate(doc.pay_contract_end_date)\n  date_entree_end = frappe.utils.getdate(doc.pay_starting_date)\n  \n  start_date = doc.pay_starting_date\n  end_date = doc.pay_contract_end_date\n  \n  Net_Paye = 0\n  NombreJourAnn = 0\n  Somme = 0\n  years = 0\n  ratio_find = 0\n  \n  fiscal_year = date_actuelle_end.year\n  # Calculate the difference in years\n  years = date_actuelle_end.year - date_entree_end.year\n \n  jour_entree = date_entree_end.day\n  mois_entree = date_entree_end.month\n  jour_actuelle = date_actuelle_end.day\n  mois_actuelle = date_actuelle_end.month\n \n  date_entree_end = frappe.utils.getdate(doc.pay_starting_date)\n  \n  # Difference in years\n  years = date_actuelle_end.year - date_entree_end.year\n  if date_actuelle_end.month < date_entree_end.month or (date_actuelle_end.month == date_entree_end.month and date_actuelle_end.day < date_entree_end.day):\n  years = years\n \n  # Difference in months\n  months = date_actuelle_end.month - date_entree_end.month\n  if date_actuelle_end.day < date_entree_end.day:\n  months = months - 1\n  if months < 0:\n  months = months + 12\n  years = years - 1\n \n  # Compare only the days of the month\n  if date_actuelle_end.day >= date_entree_end.day:\n  days = date_actuelle_end.day - date_entree_end.day\n  else:\n  previous_month = (date_actuelle_end.month - 1) if date_actuelle_end.month > 1 else 12\n  previous_year = date_actuelle_end.year if date_actuelle_end.month > 1 else date_actuelle_end.year - 1\n  days_in_previous_month = (frappe.utils.getdate(f\"{previous_year}-{previous_month + 1}-01\") - frappe.utils.getdate(f\"{previous_year}-{previous_month}-01\")).days\n  days = (date_actuelle_end.day + int(days_in_previous_month)) - date_entree_end.day\n \n  # Display the results\n  doc.pay_seniority = f\"{years} ans, {months} pay_month, {days} jours\"\n \n  doc.pay_seniority_years = years\n  \n  if doc.pay_automatic:\n  \n  months_list = [\n  \"pay_january\", \"pay_february\", \"pay_march\", \"pay_april\", \"pay_may\", \"pay_june\",\n  \"pay_july\", \"pay_august\", \"pay_september\", \"pay_october\", \"pay_november\", \"pay_december\"\n  ]\n  \n  unions = []\n  params = []\n  \n  for m in months_list:\n  unions.append(f\"\"\"\n  SELECT r.{m} AS val\n  FROM `tabPay Provision` p\n  LEFT JOIN `tabPay Provision Ratio` r ON r.parent = p.name\n  WHERE p.fiscal_year = %s AND r.employee = %s\n  \"\"\")\n  params.extend([fiscal_year, doc.employee])\n  \n  requet = f\"\"\"\n  SELECT val, COUNT(*) AS repetitions\n  FROM (\n  {\" UNION ALL \".join(unions)}\n  ) AS t\n  WHERE val IS NOT NULL\n  GROUP BY val\n  HAVING COUNT(*) > 1\n  ORDER BY repetitions DESC;\n  \"\"\"\n  \n  pay_ratio = frappe.db.sql(requet, tuple(params), as_dict=True)\n  frappe.msgprint(f\" Ration {pay_ratio}.\")\n  if pay_ratio and len(pay_ratio) > 0 and pay_ratio[0].get(\"val\"):\n  ratio_find = pay_ratio[0].val\n  frappe.msgprint(f\" Ration {ratio_find}.\")\n  else:\n  ratio_find = doc.custom_ratio_compensation\n \n \n  # V\u00e9rification du pay_ratio\n  #if not ratio_find or ratio_find == 0:\n  #frappe.throw(\"Veuillez renseigner le pay_ratio de compensation.\")\n  \n  if days == 0:\n  doc.pay_compensatory_leave_2 = int(months) * ratio_find\n  else:\n  doc.pay_compensatory_leave_2 = (int(months) + 1) * ratio_find\n \n  if days == 0:\n  doc.pay_gratuity_amount = ((mois_actuelle - 1) * 26) / 12\n  else:\n  doc.pay_gratuity_amount = (mois_actuelle * 26) / 12\n \n  pay_notice = 0\n  \n  if doc.pay_notice_type == \"Sans Pr\u00e9avis\" :\n  doc.pay_notice = 0\n  else :\n  if doc.pay_departure_reason == \"Licenciement\" :\n  \n  if doc.pay_employee_category:\n  \n  if doc.pay_employee_category == \"CATEGORIE 1 A 5\":\n  pay_notice = 7 * years\n  doc.pay_notice = (pay_notice + 14)\n  \n  elif doc.pay_employee_category == \"AGENT DE MAITRISE\":\n  pay_notice = 9 * years\n  doc.pay_notice = (pay_notice + 26)\n  elif doc.pay_employee_category == \"CADRE DE COLLABORATION\" or doc.pay_employee_category == \"CADRE DE DIRECTION\":\n  pay_notice = 16 * years\n  doc.pay_notice = (pay_notice + 78)\n  else:\n  doc.pay_seniority_years = years\n  else :\n  \n  if doc.pay_employee_category:\n  \n  if doc.pay_employee_category == \"CATEGORIE 1 A 5\":\n  pay_notice = 7 * years\n  doc.pay_notice = (pay_notice + 14) / 2\n  \n  elif doc.pay_employee_category == \"AGENT DE MAITRISE\":\n  pay_notice = 9 * years\n  doc.pay_notice = (pay_notice + 26) / 2\n  elif doc.pay_employee_category == \"CADRE DE COLLABORATION\" or doc.pay_employee_category == \"CADRE DE DIRECTION\":\n  pay_notice = 16 * years\n  doc.pay_notice = (pay_notice + 78) / 2\n  else:\n  doc.pay_seniority_years = years\n  \n  \n  \n  #doc.pay_leave_on_notice = (doc.pay_notice * 26) / (26 * 12) - 0.55\n  doc.pay_leave_on_notice = (doc.pay_notice * 26) / (26 * 12)\n  \n  # Calculate the number of days between the two dates\n  NbreJourPeriode = frappe.utils.date_diff(end_date, start_date)\n  \n  #doc.pay_daily_rate = doc.pay_salary / 26\n  \n  # Initialize variables to 0 if they are None\n  doc.pay_compensatory_leave_2 = doc.pay_compensatory_leave_2 or 0\n  doc.pay_worked_days = doc.pay_worked_days or 0\n  doc.pay_untaken_leave = doc.pay_untaken_leave or 0\n  #doc.pay_public_holidays = doc.pay_public_holidays or 0\n  doc.pay_leave_on_notice = doc.pay_leave_on_notice or 0\n  #doc.pay_sick_days = doc.pay_sick_days or 0\n  doc.pay_notice = doc.pay_notice or 0\n  doc.pay_gratuity_amount = doc.pay_gratuity_amount or 0\n  \n  totalNbreJour = (\n  doc.pay_compensatory_leave_2 +\n  doc.pay_worked_days + \n  doc.pay_untaken_leave + \n  doc.pay_leave_on_notice +\n  doc.pay_notice + \n  doc.pay_gratuity_amount\n  )\n \n  doc.pay_total_days = totalNbreJour\n "
        exec(script, {"self": self, "frappe": frappe, "doc": self})

